const body = $input.item.json.body || {};
const vault = body.vault || 'default_vault';
const filename = body.filename || `Zettel_${Date.now()}.md`;
const frontmatter = body.frontmatter || {};
const content = body.content || '';

// Generate YAML Frontmatter
let fmString = '---\n';
for (const [key, val] of Object.entries(frontmatter)) {
  if (Array.isArray(val)) {
    fmString += `${key}:\n`;
    val.forEach(item => {
      fmString += `  - "${item.replace(/"/g, '\"')}"\n`;
    });
  } else if (typeof val === 'object' && val !== null) {
    fmString += `${key}:\n`;
    for (const [subKey, subVal] of Object.entries(val)) {
      fmString += `  ${subKey}: "${String(subVal).replace(/"/g, '\"')}"\n`;
    }
  } else {
    fmString += `${key}: "${String(val).replace(/"/g, '\"')}"\n`;
  }
}
fmString += '---\n';

const fullMarkdown = `${fmString}${content}`;
const repoPath = `vaults/${vault}/${filename}`;

return {
  json: {
    vault,
    filename,
    repoPath,
    fullMarkdown,
    base64Content: Buffer.from(fullMarkdown).toString('base64'),
    commitMessage: `chore(db): update ${filename} in ${vault}`
  }
};
